import numpy as np

# A "trained" linear classifier: a few large, important weights and many tiny ones.
rng = np.random.default_rng(0)
X = rng.standard_normal((500, 20))
W_true = np.zeros(20)
W_true[:5] = [3.0, -2.5, 2.0, -1.5, 1.0]
y = (X @ W_true > 0).astype(int)
W_trained = W_true + rng.standard_normal(20) * 0.05


def accuracy(W):
    return float(np.mean((X @ W > 0).astype(int) == y))


def prune_by_magnitude(W, fraction):
    pruned = W.copy()
    k = int(round(fraction * W.size))
    smallest = np.argsort(np.abs(W), axis=None)[:k]
    pruned.flat[smallest] = 0.0
    return pruned


def sparsity(W):
    return float(np.mean(W == 0))


def max_safe_pruning(W, levels, accuracy_fn, threshold):
    best = 0.0
    for level in levels:
        if accuracy_fn(prune_by_magnitude(W, level)) >= threshold:
            best = max(best, level)
    return best


def quantize_int8(W):
    scale = np.max(np.abs(W)) / 127
    q = np.clip(np.round(W / scale), -127, 127).astype(np.int8)
    return q, scale


def dequantize(q, scale):
    return q.astype(float) * scale


levels = [0.1, 0.3, 0.5, 0.7, 0.9]
for level in levels:
    pruned = prune_by_magnitude(W_trained, level)
    if pruned is not None:
        print(f"prune {level:.0%}: sparsity {sparsity(pruned):.2f}, accuracy {accuracy(pruned):.3f}")
print("max pruning keeping >= 95% accuracy:", max_safe_pruning(W_trained, levels, accuracy, 0.95))
result = quantize_int8(W_trained)
if result is not None:
    q, scale = result
    print("int8 weights:", q.dtype, "bytes:", W_trained.nbytes, "->", q.nbytes)
    print("max quantization error:", round(float(np.max(np.abs(dequantize(q, scale) - W_trained))), 4))
